@Injectable()
export class LambdaService {
  constructor(private readonly lazyModuleLoader: LazyModuleLoader) {}

  async handle() {
    const { LazyModule } = await import('./lazy.module.js');
    const moduleRef = await this.lazyModuleLoader.load(() => LazyModule);

    const { LazyService } = await import('./lazy.service.js');
    return moduleRef.get(LazyService).run();
  }
}

@Injectable()
export class LoggingGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const type = context.getType(); // 'http' | 'rpc' | 'ws' | 'graphql'
    if (type === 'http') {
      const ctx = context.switchToHttp();
      const request = ctx.getRequest<Request>();
      const response = ctx.getResponse<Response>();
      // 仅在 HTTP 上下文中处理 request / response
      return Boolean(request && response);
    }
    return true;
  }
}

export const Roles = Reflector.createDecorator<string[]>();

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const roles = this.reflector.getAllAndOverride<string[]>(Roles, [
      context.getHandler(),
      context.getClass(),
    ]);
    return !roles?.length;
  }
}

